# save as decode_clasic2.py
s = """"""
# (the string above is the numeric string you had after base62->base58 step)

# 1) split by separator '11' (author's clue)
tokens = [t for t in s.split("11") if t != ""]

print("Unique tokens found:", sorted(set(tokens)) )

# common tokens expected: '88','99','44','55'
# We'll try two likely mappings:
mappings = [
    {'88':'0','99':'1','44':'0','55':'1'},  # mapping A (88->0, 99->1)
    {'88':'1','99':'0','44':'1','55':'0'},  # mapping B (inverted)
]

def decode_with_map(tokens, mp):
    bits = ''.join(mp.get(t, '') for t in tokens)   # ignore unknown tokens
    # trim bits length to multiple of 8
    n = (len(bits) // 8) * 8
    bits = bits[:n]
    chars = []
    for i in range(0, len(bits), 8):
        byte = bits[i:i+8]
        try:
            chars.append(chr(int(byte,2)))
        except:
            chars.append('?')
    return ''.join(chars)

for idx, mp in enumerate(mappings, 1):
    text = decode_with_map(tokens, mp)
    print("\n=== Mapping", idx, "===")
    print("mapping:", mp)
    print("decoded (first 400 chars):\n")
    print(text[:400])
    print("\n----------\n")
